CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY,"email" TEXT UNIQUE,"phone" TEXT UNIQUE,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"birthDate" DATETIME NOT NULL,"avatarUrl" TEXT,"place" TEXT NOT NULL DEFAULT 'Гальнево',"bio" TEXT,"profession" TEXT,"interests" TEXT NOT NULL DEFAULT '[]',"skills" TEXT NOT NULL DEFAULT '[]',"role" TEXT NOT NULL DEFAULT 'USER',"verified" BOOLEAN NOT NULL DEFAULT false,"locationVisible" BOOLEAN NOT NULL DEFAULT false,"lat" REAL,"lng" REAL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE TABLE "Post" ("id" TEXT NOT NULL PRIMARY KEY,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"category" TEXT NOT NULL,"type" TEXT NOT NULL DEFAULT 'GENERAL',"expiresAt" DATETIME,"lat" REAL,"lng" REAL,"authorId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY("authorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Event" ("id" TEXT NOT NULL PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"imageUrl" TEXT,"startsAt" DATETIME NOT NULL,"endsAt" DATETIME NOT NULL,"lat" REAL NOT NULL,"lng" REAL NOT NULL,"placeName" TEXT NOT NULL,"minAge" INTEGER,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"organizerId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("organizerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Attendance" ("id" TEXT NOT NULL PRIMARY KEY,"status" TEXT NOT NULL,"userId" TEXT NOT NULL,"eventId" TEXT NOT NULL,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Attendance_userId_eventId_key" ON "Attendance"("userId","eventId");
CREATE TABLE "Message" ("id" TEXT NOT NULL PRIMARY KEY,"body" TEXT NOT NULL,"senderId" TEXT NOT NULL,"receiverId" TEXT,"eventId" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY("receiverId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Notification" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"read" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Report" ("id" TEXT NOT NULL PRIMARY KEY,"reason" TEXT NOT NULL,"details" TEXT,"status" TEXT NOT NULL DEFAULT 'OPEN',"reporterId" TEXT NOT NULL,"targetUserId" TEXT,"targetPostId" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("reporterId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY("targetPostId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Block" ("id" TEXT NOT NULL PRIMARY KEY,"blockerId" TEXT NOT NULL,"blockedId" TEXT NOT NULL,FOREIGN KEY("blockerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY("blockedId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Block_blockerId_blockedId_key" ON "Block"("blockerId","blockedId");
CREATE TABLE "Review" ("id" TEXT NOT NULL PRIMARY KEY,"rating" INTEGER NOT NULL,"text" TEXT NOT NULL,"reviewerId" TEXT NOT NULL,"revieweeId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("reviewerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY("revieweeId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "CalendarEntry" ("id" TEXT NOT NULL PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT,"startsAt" DATETIME NOT NULL,"endsAt" DATETIME NOT NULL,"placeName" TEXT,"lat" REAL,"lng" REAL,"visibility" TEXT NOT NULL DEFAULT 'PRIVATE',"userId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "PushSubscription" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"endpoint" TEXT NOT NULL UNIQUE,"p256dh" TEXT NOT NULL,"auth" TEXT NOT NULL,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Post_createdAt_idx" ON "Post"("createdAt");
CREATE INDEX "Event_startsAt_idx" ON "Event"("startsAt");
CREATE INDEX "Notification_userId_read_idx" ON "Notification"("userId","read");
